<template><view v-show="props.visible" class="cw-dialog" role="dialog" :aria-label="title" @tap.self="emit('close')"><view class="cw-dialog-panel"><text class="cw-subtitle">{{ title }}</text><text class="cw-scope">当前{{ props.kind==='adjust_money'?'余额':'积分' }}：{{ props.currentValue===null?'记录异常，暂不可调整':props.currentValue }}。减少数量以实际可扣额度为准；提交后重新读取。</text><label class="cw-form-field"><text>调整方向</text><picker :range="directions" range-key="name" :value="direction==='add'?0:1" :disabled="props.busy||props.currentValue===null" @change="direction=Number($event.detail.value)===0?'add':'subtract'"><view>{{ direction==='add'?'增加':'减少' }}</view></picker></label><label class="cw-form-field"><text>{{ props.kind==='adjust_money'?'金额':'积分数量' }}</text><input v-model="value" :type="props.kind==='adjust_money'?'digit':'number'" :disabled="props.busy||props.currentValue===null" :placeholder="props.kind==='adjust_money'?'正数，最多两位小数':'正整数'" :aria-label="props.kind==='adjust_money'?'调整余额金额':'调整积分数量'" /></label><text v-if="localError||props.error" class="cw-error">{{ localError||props.error }}</text><view class="cw-dialog-buttons"><button :disabled="props.busy" @tap="emit('close')">取消</button><button :disabled="props.busy||props.currentValue===null" @tap="submit">确认调整</button></view></view></view></template>
<script setup lang="ts">
import { computed,ref,watch } from 'vue';import { customerWorkUserAmount,customerWorkUserPositive,CUSTOMER_WORK_USER_NAMES } from '@/utils/customerWorkUsersContract';
const props=defineProps<{visible:boolean;kind:'adjust_money'|'adjust_integral';currentValue:string|number|null;busy:boolean;error:string}>(),emit=defineEmits<{close:[];submit:[payload:{direction:'add'|'subtract';amount:string|number}]} >();
const directions=[{name:'增加'},{name:'减少'}],direction=ref<'add'|'subtract'>('add'),value=ref(''),localError=ref(''),title=computed(()=>CUSTOMER_WORK_USER_NAMES[props.kind]);watch(()=>[props.visible,props.kind],()=>{direction.value='add';value.value='';localError.value='';},{immediate:true});
function submit(){if(props.busy||props.currentValue===null)return;try{emit('submit',{direction:direction.value,amount:props.kind==='adjust_money'?customerWorkUserAmount(value.value):customerWorkUserPositive(value.value)});}catch(failure){localError.value=failure instanceof Error?failure.message:'调整数量无效';}}
</script>
